      {site.weekdayHours && (
        <div>
          <dt>{site.weekdayHoursLabel}</dt>
          <dd>{site.weekdayHours}</dd>
        </div>
      )}
    </dl>
  )
}

---
interface Props {
  /** The page's h1, read from a site field. */
  heading: string
  /** One sentence under the heading, read from a site field. */
  lede?: string
}

const { heading, lede = "" } = Astro.props
